/**
 * `tests/unit/workspace/generated-artifacts-stamp-content.test.ts`
 *
 * The generated-artifact verdict follows the CONTENT, not the release number.
 *
 * The symptom this pins down: `peaks skill presence --json` reported
 * `stale: true` with the reason `package-upgraded` on every command, because
 * the stamp recorded the release that last ran `peaks workspace init` and that
 * release number moves on every publish while the generated bytes stand still.
 * A warning that fires on every turn and never asks for an action is noise, and
 * noise is what this file's subject is about.
 *
 * The four verdicts that matter are pinned here, each against a real project
 * tree produced by the real `initWorkspace`:
 *   - a version drift with unchanged content is NOT stale;
 *   - content that differs IS stale, and the reason names the file;
 *   - a different template shape IS stale;
 *   - no stamp, or an unreadable stamp, IS stale.
 *
 * Dimensions covered:
 *   - behavior:    the verdict per reason code
 *   - integration: a real `initWorkspace` against a real tmp project tree
 *   - render:      the warning text the reader gets
 *   - a11y:        the warning is one plain sentence naming its subject
 */

import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';

import { declareDimensions } from '../_setup/4dim-template.js';
import { withTmpWorkspacePerTest } from '../_setup/tmp-workspace.js';
import { generatedConfigNotice } from '~/src/cli/commands/core/skill-generated-config-notice';
import {
  detectStaleGeneratedArtifacts,
  generatedArtifactsStampPath,
  writeGeneratedArtifactsStamp
} from '~/src/services/workspace/generated-artifacts-stamp';
import { initWorkspace } from '~/src/services/workspace/workspace-service';

declareDimensions('tests/unit/workspace/generated-artifacts-stamp-content.test.ts', [
  'behavior',
  'integration',
  'render',
  'a11y'
]);

const SESSION_ID = '2026-10-23-session-abcdef';
const getWs = withTmpWorkspacePerTest('peaks-stamp-content-');
const SETTINGS_REL = '.claude/settings.local.json';

/** Materialize a project the way `peaks workspace init` does. */
async function initProject(projectRoot: string): Promise<void> {
  await initWorkspace({ projectRoot, sessionId: SESSION_ID });
}

/** Overwrite one key of the generated settings file, leaving the rest intact. */
function rewriteEnvKey(projectRoot: string, key: string, value: string): void {
  const path = join(projectRoot, '.claude', 'settings.local.json');
  const parsed = JSON.parse(readFileSync(path, 'utf8')) as { env: Record<string, string> };
  parsed.env[key] = value;
  writeFileSync(path, `${JSON.stringify(parsed, null, 2)}\n`, 'utf8');
}

describe('behavior — the verdict follows the content', () => {
  it('when the release moved on but the content matches, should not be stale', async () => {
    // given: a project whose generated artifacts match the current template
    // when: the release that wrote them moved on, but the content did not
    // then: the verdict is NOT stale, and the release is reported as information
    const ws = getWs();
    await initProject(ws.path);

    // What `npm i -g peaks-loop@<newer>` leaves behind: the same generated
    // bytes, written by an older release.
    writeGeneratedArtifactsStamp(ws.path, {
      packageVersion: '4.0.40',
      now: new Date('2026-09-01T00:00:00.000Z')
    });

    const staleness = detectStaleGeneratedArtifacts(ws.path);
    expect(staleness.stale).toBe(false);
    // The release that wrote the artifacts is still reported — as information.
    expect(staleness.reasons).toContain('package-upgraded');
    expect(staleness.reasons).not.toContain('content-drift');
    expect(staleness.drift).toEqual([]);
  });

  it('when the content differs, should be stale and the reason name the artifact', async () => {
    // given: a generated artifact a key was edited in by hand
    // when: the staleness of the project is detected
    // then: it IS stale, and the reason names the artifact
    const ws = getWs();
    await initProject(ws.path);

    // A key the template owns, edited by hand after the init.
    rewriteEnvKey(ws.path, 'GATEGUARD_EXEMPT_GLOBS', 'somewhere-else/**');

    const staleness = detectStaleGeneratedArtifacts(ws.path);
    expect(staleness.stale).toBe(true);
    expect(staleness.reasons).toContain('content-drift');
    const drift = staleness.drift.filter((entry) => entry.artifact === SETTINGS_REL);
    expect(drift.length).toBeGreaterThan(0);
    expect(drift.map((entry) => entry.detail).join(' ')).toContain('GATEGUARD_EXEMPT_GLOBS');
  });

  it('when the template shape differs, should be staleness', async () => {
    // given: a project whose stamp names a template shape this build lacks
    // when: the staleness of the project is detected
    // then: it IS stale, and the reason names the template
    const ws = getWs();
    await initProject(ws.path);
    writeGeneratedArtifactsStamp(ws.path, { packageVersion: '4.0.40' });
    const stampPath = generatedArtifactsStampPath(ws.path);
    const stamp = JSON.parse(readFileSync(stampPath, 'utf8')) as Record<string, unknown>;
    stamp['templateVersion'] = '0.0.1-not-a-real-shape';
    writeFileSync(stampPath, `${JSON.stringify(stamp, null, 2)}\n`, 'utf8');

    const staleness = detectStaleGeneratedArtifacts(ws.path);
    expect(staleness.stale).toBe(true);
    expect(staleness.reasons).toContain('template-changed');
  });

  it('when the artifacts carry no stamp, should be staleness (unstamped)', () => {
    // given: generated artifacts on disk with no stamp beside them
    // when: the staleness of the project is detected
    // then: it IS stale, and the only reason is `unstamped`
    const ws = getWs();
    mkdirSync(join(ws.path, '.claude'), { recursive: true });
    writeFileSync(join(ws.path, '.claude', 'settings.local.json'), '{}\n', 'utf8');

    const staleness = detectStaleGeneratedArtifacts(ws.path);
    expect(staleness.stale).toBe(true);
    expect(staleness.reasons).toEqual(['unstamped']);
  });

  it('when the stamp cannot be parsed, should be staleness (stamp-unreadable)', async () => {
    // given: a stamp file this build cannot parse
    // when: the staleness of the project is detected
    // then: it IS stale, and the only reason is `stamp-unreadable`
    const ws = getWs();
    await initProject(ws.path);
    writeFileSync(generatedArtifactsStampPath(ws.path), '{ not json', 'utf8');

    const staleness = detectStaleGeneratedArtifacts(ws.path);
    expect(staleness.stale).toBe(true);
    expect(staleness.reasons).toEqual(['stamp-unreadable']);
  });
});

describe('integration — a real initialized project', () => {
  it('when a project is freshly initialized, should not be stale and carry no drift', async () => {
    // given: a project initialized by the current release
    // when: the staleness of the project is detected
    // then: it is not stale, and it carries no drift
    const ws = getWs();
    await initProject(ws.path);

    const staleness = detectStaleGeneratedArtifacts(ws.path);
    expect(staleness.stale).toBe(false);
    expect(staleness.reasons).toEqual([]);
    expect(staleness.drift).toEqual([]);
  });
});

describe('render — the warning the reader gets', () => {
  it('when the content differs, should name the file and what about it', async () => {
    // given: a generated artifact a key was edited in by hand
    // when: the notice the reader gets is rendered
    // then: it names the file and what about it
    const ws = getWs();
    await initProject(ws.path);
    rewriteEnvKey(ws.path, 'GATEGUARD_EXEMPT_GLOBS', 'somewhere-else/**');

    const notice = generatedConfigNotice(ws.path);
    expect(notice.warnings.length).toBe(1);
    const warning = notice.warnings[0] ?? '';
    expect(warning).toContain(SETTINGS_REL);
    expect(warning).toContain('GATEGUARD_EXEMPT_GLOBS');
    // The remedy is in the message: the reader must not have to guess it.
    expect(warning).toContain('peaks workspace init');
    // The envelope carries the same detail for a machine reader.
    const field = notice.field['generatedArtifacts'] as { drift: { artifact: string }[] };
    expect(field.drift.map((entry) => entry.artifact)).toContain(SETTINGS_REL);
  });
});

describe('a11y — no warning when there is nothing to do', () => {
  it('when the release drifted but the content did not, should carry NO warning', async () => {
    // given: a release that moved on over unchanged generated artifacts
    // when: the notice the reader gets is rendered
    // then: it carries no warning and no field
    const ws = getWs();
    await initProject(ws.path);
    writeGeneratedArtifactsStamp(ws.path, { packageVersion: '4.0.40' });

    const notice = generatedConfigNotice(ws.path);
    expect(notice.warnings).toEqual([]);
    expect(notice.field['generatedArtifacts']).toBeUndefined();
  });
});
